    "WindowsEvent", "EventData", "IP-P1, IP-P2, IP-P4, IP-P6, IP-S1, IP-S2, IP-S3, IP-S4, IP-T1, IP-T2, IP-T3",
    "WindowsEvent", "EventID", "IP-P1, IP-P2, IP-P4, IP-P6, IP-S1, IP-S2, IP-S3, IP-S4, IP-T1, IP-T2, IP-T3",
    "WindowsEvent", "Provider", "IP-P1, IP-P2, IP-P4, IP-P6, IP-S1, IP-S2, IP-S3, IP-S4, IP-T1, IP-T2, IP-T3",
    "WindowsEvent", "RawEventData", "IP-P1, IP-P2, IP-P4, IP-P6, IP-S1, IP-S2, IP-S3, IP-S4, IP-T1, IP-T2, IP-T3"
