    "DeviceProcessEvents", "FileName", "EM-T1",
    "DeviceProcessEvents", "InitiatingProcessFileName", "EM-T1",
    "DeviceProcessEvents", "ProcessCommandLine", "EM-T1",
    "EmailAttachmentInfo", "FileName", "EM-P4",
    "EmailAttachmentInfo", "FileSize", "EM-P4",
    "EmailAttachmentInfo", "FileType", "EM-P4",
    "EmailAttachmentInfo", "NetworkMessageId", "EM-P4",
    "EmailAttachmentInfo", "SHA256", "EM-P4",
    "EmailAttachmentInfo", "ThreatNames", "EM-P4",
    "EmailAttachmentInfo", "ThreatTypes", "EM-P4",
    "EmailEvents", "AttachmentCount", "EM-P1",
    "EmailEvents", "AuthenticationDetails", "EM-P1, EM-S2",
    "EmailEvents", "DeliveryAction", "EM-P1, EM-P5, EM-P6, EM-S1, EM-T1",
    "EmailEvents", "DeliveryLocation", "EM-P5",
    "EmailEvents", "DetectionMethods", "EM-P1",
    "EmailEvents", "EmailDirection", "EM-P1, EM-P6, EM-S2",
