    "EmailEvents", "SenderDisplayName", "EM-P1",
    "EmailEvents", "SenderFromAddress", "EM-P1, EM-P2, EM-P4, EM-P5, EM-P6, EM-S1, EM-S2, EM-T1",
    "EmailEvents", "SenderFromDomain", "EM-S2",
    "EmailEvents", "SenderIPv4", "EM-P1, EM-S2",
    "EmailEvents", "SenderMailFromAddress", "EM-P1, EM-P4, EM-S1, EM-S2",
    "EmailEvents", "SenderMailFromDomain", "EM-S2",
    "EmailEvents", "Subject", "EM-P1, EM-P2, EM-P4, EM-P5, EM-P6, EM-S2, EM-T1",
    "EmailEvents", "ThreatTypes", "EM-P1, EM-P5, EM-S1, EM-S2, EM-T1",
    "EmailEvents", "UrlCount", "EM-P1",
    "EmailPostDeliveryEvents", "Action", "EM-P5",
    "EmailPostDeliveryEvents", "ActionResult", "EM-P5",
