    "MicrosoftGraphActivityLogs", "RequestUri", "AP-P2",
    "MicrosoftGraphActivityLogs", "ResponseStatusCode", "AP-P2, AP-S1",
    "MicrosoftGraphActivityLogs", "ServicePrincipalId", "AP-P2, AP-S1",
    "MicrosoftGraphActivityLogs", "UserId", "AP-P2, AP-S1",
    "SigninLogs", "AppDisplayName", "AP-S1",
    "SigninLogs", "AppId", "AP-S1",
    "SigninLogs", "AuthenticationRequirement", "AP-S1",
    "SigninLogs", "AutonomousSystemNumber", "AP-S1",
