    "CommonSecurityLog", "DeviceAction", "HS-P2",
    "CommonSecurityLog", "DeviceProduct", "HS-P2",
    "CommonSecurityLog", "DeviceVendor", "HS-P2",
    "CommonSecurityLog", "FileHash", "HS-P2, HS-S1",
