    "DeviceFileEvents", "FileName", "HS-P1, HS-P2",
    "DeviceFileEvents", "FileOriginIP", "HS-P2",
    "DeviceFileEvents", "FileOriginReferrerUrl", "HS-P2",
    "DeviceFileEvents", "FileOriginUrl", "HS-P2",
    "DeviceFileEvents", "FolderPath", "HS-P1, HS-P2",
    "DeviceFileEvents", "InitiatingProcessAccountName", "HS-P1",
    "DeviceFileEvents", "InitiatingProcessCommandLine", "HS-P2",
    "DeviceFileEvents", "InitiatingProcessFileName", "HS-P1, HS-P2",
    "DeviceFileEvents", "MD5", "HS-P1, HS-P2",
