    "DeviceProcessEvents", "FileName", "HS-P1",
    "DeviceProcessEvents", "FolderPath", "HS-P1",
    "DeviceProcessEvents", "InitiatingProcessFileName", "HS-P1",
    "DeviceProcessEvents", "MD5", "HS-P1",
    "DeviceProcessEvents", "SHA1", "HS-P1",
    "DeviceProcessEvents", "SHA256", "HS-P1",
    "EmailAttachmentInfo", "FileName", "HS-P2, HS-S1",
    "EmailAttachmentInfo", "RecipientEmailAddress", "HS-P2, HS-S1",
    "EmailAttachmentInfo", "SenderFromAddress", "HS-P2",
    "EmailAttachmentInfo", "SHA256", "HS-P2, HS-S1",
