var currentMode = "light";
function detectThemeMode() {
  if (document.documentElement.classList.contains("fxs-mode-dark") || document.body?.classList.contains("fxs-mode-dark")) {
    return "dark";
  }
  try {
    const parentDoc = window.parent?.document;
    if (parentDoc) {
      if (parentDoc.documentElement?.classList.contains("fxs-mode-dark") || parentDoc.body?.classList.contains("fxs-mode-dark")) {
        return "dark";
      }
    }
  } catch {
  }
  try {
    if (typeof unsafeWindow !== "undefined") {
      const parentDoc = unsafeWindow.parent?.document;
      if (parentDoc) {
        if (parentDoc.documentElement?.classList.contains("fxs-mode-dark") || parentDoc.body?.classList.contains("fxs-mode-dark")) {
          return "dark";
        }
      }
    }
  } catch {
  }
  try {
    const bg = window.getComputedStyle(document.body).backgroundColor;
    if (bg && bg !== "transparent" && bg !== "rgba(0, 0, 0, 0)") {
      const match = bg.match(/\d+/g);
      if (match && match.length >= 3) {
        const [r, g, b] = match.map(Number);
        const luminance = 0.299 * r + 0.587 * g + 0.114 * b;
        if (luminance < 128) {
          return "dark";
        }
      }
    }
  } catch {
  }
  return "light";
}
function buildTokenCSS(mode) {
  const tokens = mode === "dark" ? DARK_TOKENS : LIGHT_TOKENS;
  const vars = Object.entries(tokens).map(([k, v]) => `  ${k}: ${v};`).join("\n");
  return `:root {
${vars}
}`;
}
