// src/styles/index.ts
var injected = false;
function injectStyles() {
  if (injected) return;
  injected = true;
  const style = document.createElement("style");
  style.id = `${CSS_PREFIX}-styles`;
  style.textContent = [
    buttonStyles,
    popupStyles,
    notificationStyles,
    pivotStyles,
    caseViewStyles,
    reportDialogStyles
  ].join("\n");
  document.head.appendChild(style);
}

// src/core/normalize.ts
var INVISIBLE_RE = /[\u200b-\u200d\ufeff]/g;
var UNICODE_SPACE_RE = /[\u00a0\u2000-\u200a\u202f\u205f\u3000]/g;
var WRAPPING_QUOTES_RE = /^(["'`])([\s\S]*)\1$/;
var REFANG_DOT_RE = /([A-Za-z0-9])[([{]\.[)\]}]/g;
var REFANG_COLON_RE = /([A-Za-z0-9])\[:\]/g;
var REFANG_AT_RE = /\[@\]|\(at\)/gi;
var REFANG_SCHEME_RE = /\bhxxps?\b/gi;
function refangScheme(s) {
  return s.replace(REFANG_SCHEME_RE, (m) => m.toLowerCase() === "hxxps" ? "https" : "http");
}
function preNormalize(value) {
  if (typeof value !== "string") return "";
  try {
    let v = value.replace(INVISIBLE_RE, "").replace(UNICODE_SPACE_RE, " ").trim();
    if (v === "") return "";
    const quoted = WRAPPING_QUOTES_RE.exec(v);
    if (quoted) v = quoted[2].trim();
    v = refangScheme(v);
    v = v.replace(REFANG_AT_RE, "@");
    let prev;
    do {
      prev = v;
      v = v.replace(REFANG_DOT_RE, "$1.");
      v = v.replace(REFANG_COLON_RE, "$1:");
    } while (v !== prev);
    return v;
  } catch (err) {
    log.error("preNormalize failed, returning raw value", err);
    return value;
  }
}
var IPV4_RE = /^(25[0-5]|2[0-4]\d|1\d\d|[1-9]?\d)(\.(25[0-5]|2[0-4]\d|1\d\d|[1-9]?\d)){3}$/;
var IPV4_MAPPED_RE = /^::ffff:(\d{1,3}(?:\.\d{1,3}){3})$/i;
var BRACKETED_HOST_PORT_RE = /^\[(.+)]:\d+$/;
var IPV4_PORT_RE = /^(\d{1,3}(?:\.\d{1,3}){3}):\d+$/;
function stripPort(value) {
  const bracketed = BRACKETED_HOST_PORT_RE.exec(value);
  if (bracketed) return bracketed[1];
  const ipv4Port = IPV4_PORT_RE.exec(value);
  if (ipv4Port && IPV4_RE.test(ipv4Port[1])) return ipv4Port[1];
  return value;
}
function stripIPv4Mapped(value) {
  const m = IPV4_MAPPED_RE.exec(value);
  return m ? m[1] : value;
}
function normalizeIp(value) {
  return stripIPv4Mapped(stripPort(value));
}
function normalizeEmail(value) {
  const at = value.lastIndexOf("@");
  if (at < 0) return value;
  return value.slice(0, at + 1) + value.slice(at + 1).toLowerCase();
}
function normalize(value, type) {
  const pre = preNormalize(value);
  if (pre === "") return "";
  try {
    let out = pre;
    switch (type) {
      case "ip":
        out = normalizeIp(pre);
        break;
      case "hash":
        out = pre.toLowerCase();
        break;
      case "email":
        out = normalizeEmail(pre);
        break;
      case "domain":
        out = pre.toLowerCase();
        break;
      default:
        out = pre;
    }
    if (out !== value) {
      log.debug("normalize changed value", { type, before: value, after: out });
    }
    return out;
  } catch (err) {
    log.error("normalize failed, returning pre-normalized value", { type }, err);
    return pre;
  }
}

// src/core/detection.ts
